style.css:
@-moz-document url-prefix("https://www.pinterest.com/") {
body {
    background-color: #3c0d15 !important;
    color: #f5f5f5 !important;
  }

  header, nav, footer, aside {
    background-color: #2e0a12 !important;
  }

  [data-test-id="pin"] {
    background-color: #4b121e !important;
    color: #ffffff !important;
  }

  h1, h2, h3, h4, h5, h6,
  p, span, a, div, button {
    color: #f0eaea !important;
  }

  a {
    color: #e2979c !important;
  }

  button,
  .button {
    background-color: #5a1a23 !important;
    color: #fff !important;
    border: none !important;
  }

  button:hover,
  .button:hover {
    background-color: #751e2b !important;
  }

  img,
  [style*="background-image"] {
    background-color: transparent !important;
    filter: none !important;
  }

  * {
    transition: none !important;
    box-shadow: none !important;
  }
}
